-- Sample content for the library and the daily cards (user, 2026-10-25): 10 tips, 10 articles
-- and 10 videos in Uzbek, Russian and English, all published. Fixed ids, so the down migration
-- removes exactly these rows. Real content is made in the dashboard.
--
-- Tips find their topic by English name (the topics seeded in 000020), falling back to the
-- oldest active topic. Articles and videos find their goal by English name, falling back to the
-- oldest active goal; with no goals at all they are skipped. Videos need a video file: they all
-- reuse the oldest uploaded video (media with a video/* content type); with none they are skipped.

INSERT INTO tips (id, text_uz, text_ru, text_en, topic_id, min_age, max_age, status, created_at, updated_at)
SELECT v.id::uuid, v.text_uz, v.text_ru, v.text_en, COALESCE((SELECT id FROM topics WHERE deleted_at IS NULL AND LOWER(name_en) = LOWER(v.topic) ORDER BY created_at, id LIMIT 1), (SELECT id FROM topics WHERE deleted_at IS NULL ORDER BY created_at, id LIMIT 1)),
    v.min_age, v.max_age, 'published', NOW() + v.n * INTERVAL '1 millisecond', NOW()
FROM (VALUES
    (1, '5a1e0000-0000-4000-8000-000000000001', 'Food', 2, 6, 'Bolangizga ovqatni o‘zi tanlashiga imkon bering: ikki xil sabzavotdan birini tanlasin.',
     'Дайте ребёнку выбрать еду самому: пусть выберет один из двух овощей.',
     'Let your child choose: offer two vegetables and let them pick one.'),
    (2, '5a1e0000-0000-4000-8000-000000000002', 'Food', 2, 4, 'Yangi taomni bir necha marta, bosimsiz taklif qiling. Ba’zan bola 10 martadan keyin tatib ko‘radi.',
     'Предлагайте новое блюдо несколько раз и без давления. Иногда ребёнок пробует его только с десятого раза.',
     'Offer a new food several times without pressure. Some children only taste it on the tenth try.'),
    (3, '5a1e0000-0000-4000-8000-000000000003', 'Sleep', 2, 6, 'Har kuni bir xil uyqu tartibi: cho‘milish, kitob, qo‘shiq. Takror bolaga xotirjamlik beradi.',
     'Каждый вечер один и тот же ритуал: купание, книжка, песенка. Повторение успокаивает ребёнка.',
     'Keep the same bedtime routine every night: bath, book, song. Repetition helps a child settle.'),
    (4, '5a1e0000-0000-4000-8000-000000000004', 'Sleep', 3, 6, 'Uxlashdan bir soat oldin ekranlarni o‘chiring, xonani esa yorug‘ligini pasaytiring.',
     'За час до сна выключите экраны и приглушите свет в комнате.',
     'Turn off screens an hour before bed and dim the lights in the room.'),
    (5, '5a1e0000-0000-4000-8000-000000000005', 'Speech', 2, 4, 'Bolangiz nima qilayotganini ovoz chiqarib ayting: «Sen qizil koptokni olding». Bu so‘z boyligini oshiradi.',
     'Проговаривайте вслух, что делает ребёнок: «Ты взял красный мяч». Так растёт словарный запас.',
     'Say out loud what your child is doing: "You picked up the red ball." It grows their vocabulary.'),
    (6, '5a1e0000-0000-4000-8000-000000000006', 'Speech', 3, 6, '«Ha» yoki «yo‘q» bilan javob berilmaydigan savollar bering: «Bugun nima qilding?»',
     'Задавайте вопросы, на которые нельзя ответить «да» или «нет»: «Что ты сегодня делал?»',
     'Ask questions that need more than yes or no: "What did you do today?"'),
    (7, '5a1e0000-0000-4000-8000-000000000007', 'Emotions', 2, 6, 'Bolaning his-tuyg‘usini nomlang: «Sen xafa bo‘lding, chunki o‘yin tugadi». Nomlangan tuyg‘u yengilroq.',
     'Называйте чувства ребёнка: «Ты расстроился, потому что игра закончилась». Названное чувство легче пережить.',
     'Name your child''s feeling: "You are upset because the game ended." A named feeling is easier to handle.'),
    (8, '5a1e0000-0000-4000-8000-000000000008', 'Screen time', 2, 6, 'Ekran vaqtini oldindan kelishib oling va tugashidan 5 daqiqa oldin eslatib qo‘ying.',
     'Договоритесь о времени у экрана заранее и предупредите за 5 минут до конца.',
     'Agree on screen time in advance and give a five-minute warning before it ends.'),
    (9, '5a1e0000-0000-4000-8000-000000000009', 'Behaviour', 3, 6, 'Yaxshi xulqni darhol va aniq maqtang: «O‘yinchoqlarni yig‘ganing uchun rahmat».',
     'Хвалите хорошее поведение сразу и конкретно: «Спасибо, что собрал игрушки».',
     'Praise good behaviour right away and be specific: "Thank you for putting the toys away."'),
    (10, '5a1e0000-0000-4000-8000-000000000010', 'Play', 2, 6, 'Kuniga 10 daqiqa bolangiz boshqaradigan o‘yin o‘ynang: u qoidani aytadi, siz ergashasiz.',
     'Играйте 10 минут в день в игру, которой руководит ребёнок: он задаёт правила, вы следуете.',
     'Spend ten minutes a day in play your child leads: they set the rules, you follow.')
) AS v (n, id, topic, min_age, max_age, text_uz, text_ru, text_en)
WHERE (SELECT id FROM topics WHERE deleted_at IS NULL ORDER BY created_at, id LIMIT 1) IS NOT NULL
ON CONFLICT (id) DO NOTHING;

INSERT INTO articles (id, title_uz, title_ru, title_en, article_body_uz, article_body_ru, article_body_en,
    tip_uz, tip_ru, tip_en, expected_read_time, min_age, max_age, goal_id, topic_id, status, created_at, updated_at)
SELECT v.id::uuid, v.title_uz, v.title_ru, v.title_en, v.body_uz, v.body_ru, v.body_en, v.tip_uz, v.tip_ru, v.tip_en,
    v.minutes, v.min_age, v.max_age, COALESCE((SELECT id FROM goals WHERE deleted_at IS NULL AND LOWER(name_en) = LOWER(v.goal) ORDER BY created_at, id LIMIT 1), (SELECT id FROM goals WHERE deleted_at IS NULL ORDER BY created_at, id LIMIT 1)),
    (SELECT id FROM topics WHERE deleted_at IS NULL AND LOWER(name_en) = LOWER(v.topic) ORDER BY created_at, id LIMIT 1), 'published', NOW() + v.n * INTERVAL '1 millisecond', NOW()
FROM (VALUES
    (1, '5a2e0000-0000-4000-8000-000000000001', 'Language', 'Speech', 2, 4, 3,
     'Bola bilan qanday gaplashish kerak', 'Как разговаривать с малышом', 'How to talk with a toddler',
     'Bolalar so‘zlarni eshitib o‘rganadi. Kun davomida qilayotgan ishingizni oddiy so‘zlar bilan aytib boring: kiyinish, ovqat tayyorlash, sayr. Bolaning gapini to‘g‘rilamang, balki to‘g‘ri shaklda takrorlang. Javobini kuting: bolaga o‘ylash uchun vaqt kerak.',
     'Дети учат слова, слушая. В течение дня называйте простыми словами то, что вы делаете: одеваетесь, готовите, гуляете. Не поправляйте ребёнка, а повторите фразу правильно. Ждите ответа: ребёнку нужно время подумать.',
     'Children learn words by hearing them. Through the day, describe what you are doing in simple words: dressing, cooking, walking. Do not correct your child; repeat the phrase the right way instead. Wait for an answer, because a child needs time to think.',
     'Bugun sayrda 5 ta narsani nomlab ko‘ring.', 'Сегодня на прогулке назовите 5 предметов.', 'Name five things together on today''s walk.'),
    (2, '5a2e0000-0000-4000-8000-000000000002', 'Language', 'Speech', 3, 6, 4,
     'Kitobni birga o‘qish sirlari', 'Секреты совместного чтения', 'The secrets of reading together',
     'Kitob o‘qish — bu faqat matnni o‘qish emas. Rasmlar haqida so‘rang, keyin nima bo‘lishini taxmin qilishni so‘rang. Bola sevgan kitobni qayta-qayta o‘qish foydali: har safar u yangi so‘z eslab qoladi.',
     'Чтение книги — это не только текст. Спрашивайте о картинках, просите угадать, что будет дальше. Перечитывать любимую книгу полезно: каждый раз ребёнок запоминает новое слово.',
     'Reading a book is more than the words. Ask about the pictures and let your child guess what happens next. Reading a favourite book again and again helps: each time your child remembers a new word.',
     'Uxlashdan oldin bitta kitobni birga o‘qing.', 'Прочитайте вместе одну книгу перед сном.', 'Read one book together before bed.'),
    (3, '5a2e0000-0000-4000-8000-000000000003', 'Motor skills', 'Play', 2, 4, 3,
     'Kichik qo‘l mushaklari uchun o‘yinlar', 'Игры для мелкой моторики', 'Games for small hand muscles',
     'Barmoq mushaklari keyinchalik qalam ushlash va kiyinish uchun kerak. Plastilin, yirik munchoq terish, qog‘ozni yirtish va qoshiq bilan don tashish oddiy, lekin foydali mashg‘ulotlar. Mayda narsalarni faqat kattalar kuzatuvida bering.',
     'Мышцы пальцев нужны позже, чтобы держать карандаш и одеваться. Пластилин, нанизывание крупных бусин, разрывание бумаги и пересыпание крупы ложкой — простые и полезные занятия. Мелкие предметы давайте только под присмотром взрослых.',
     'Finger muscles are needed later to hold a pencil and get dressed. Play dough, threading big beads, tearing paper and moving grain with a spoon are simple and useful. Give small objects only while an adult is watching.',
     'Bugun 10 ta yirik munchoqni ipga tering.', 'Сегодня нанижите на нитку 10 крупных бусин.', 'Thread ten big beads on a string today.'),
    (4, '5a2e0000-0000-4000-8000-000000000004', 'Motor skills', NULL, 3, 6, 3,
     'Har kuni harakat qilish nega muhim', 'Почему важно двигаться каждый день', 'Why moving every day matters',
     'Maktabgacha yoshdagi bola kuniga kamida uch soat faol harakat qilishi kerak. Yugurish, sakrash, muvozanat saqlash miya rivojiga ham yordam beradi. Uyda ham yostiqlardan yo‘lak yasab, «lava» o‘yinini o‘ynash mumkin.',
     'Дошкольнику нужно не меньше трёх часов активного движения в день. Бег, прыжки и равновесие помогают и развитию мозга. Даже дома можно сделать дорожку из подушек и поиграть в «пол — это лава».',
     'A preschool child needs at least three hours of active movement a day. Running, jumping and balancing also help the brain grow. Even at home you can build a path of cushions and play "the floor is lava".',
     'Bugun yostiqlardan yo‘lak yasang.', 'Сегодня постройте дорожку из подушек.', 'Build a cushion path today.'),
    (5, '5a2e0000-0000-4000-8000-000000000005', 'Thinking', 'Play', 2, 5, 3,
     'Saralash o‘yinlari va mantiq', 'Игры на сортировку и логика', 'Sorting games and logic',
     'Narsalarni rangi, shakli yoki kattaligi bo‘yicha ajratish — mantiqiy fikrlashning birinchi qadami. Qoshiqlar va vilkalar, katta va kichik paypoqlar, qizil va ko‘k kubiklar: uydagi har bir narsa o‘yin bo‘la oladi.',
     'Сортировка по цвету, форме или размеру — первый шаг к логическому мышлению. Ложки и вилки, большие и маленькие носки, красные и синие кубики: любая вещь дома может стать игрой.',
     'Sorting things by colour, shape or size is the first step to logical thinking. Spoons and forks, big and small socks, red and blue blocks: anything at home can become a game.',
     'Kir yuvgandan keyin paypoqlarni birga juftlang.', 'После стирки разложите носки по парам вместе.', 'Match socks into pairs together after the wash.'),
    (6, '5a2e0000-0000-4000-8000-000000000006', 'Thinking', NULL, 4, 6, 4,
     '«Nega?» savollariga qanday javob berish kerak', 'Как отвечать на вопросы «почему?»', 'How to answer "why?" questions',
     'To‘rt-besh yoshda bola kuniga yuzlab savol beradi. Bu qiziquvchanlik belgisi. Qisqa va halol javob bering, ba’zan esa «Sen qanday o‘ylaysan?» deb qaytaring. Bilmasangiz, javobni birga qidiring.',
     'В четыре-пять лет ребёнок задаёт сотни вопросов в день. Это признак любознательности. Отвечайте коротко и честно, а иногда спросите в ответ: «А как ты думаешь?» Если не знаете, ищите ответ вместе.',
     'At four or five a child asks hundreds of questions a day. That is curiosity. Answer briefly and honestly, and sometimes ask back: "What do you think?" If you do not know, look for the answer together.',
     'Bugun bitta savolga javobni birga qidiring.', 'Сегодня найдите вместе ответ на один вопрос.', 'Find the answer to one question together today.'),
    (7, '5a2e0000-0000-4000-8000-000000000007', 'Social skills', 'Behaviour', 2, 4, 3,
     'Navbat kutishni o‘rgatish', 'Как научить ждать очереди', 'Teaching a child to take turns',
     'Navbat kutish ikki-uch yoshda qiyin. Qisqa o‘yinlardan boshlang: koptokni bir-biringizga dumalating va «Mening navbatim, sening navbating» deb ayting. Kutgani uchun maqtang.',
     'Ждать очереди в два-три года трудно. Начните с коротких игр: катайте мяч друг другу и говорите «Моя очередь, твоя очередь». Хвалите за то, что ребёнок подождал.',
     'Taking turns is hard at two or three. Start with short games: roll a ball back and forth and say "My turn, your turn." Praise your child for waiting.',
     'Bugun koptokni 10 marta navbat bilan dumalating.', 'Сегодня прокатите мяч по очереди 10 раз.', 'Roll a ball back and forth ten times today.'),
    (8, '5a2e0000-0000-4000-8000-000000000008', 'Social skills', NULL, 4, 6, 4,
     'Do‘st orttirishga yordam berish', 'Как помочь ребёнку найти друзей', 'Helping your child make friends',
     'Do‘stlik ko‘nikmalari o‘yin orqali o‘sadi. Bolangizni boshqa bolalar bilan qisqa uchrashuvlarga olib boring, salomlashishni va o‘yinchoqni taklif qilishni oldindan mashq qiling. Janjal bo‘lsa, darhol hal qilmang: avval bolalarning o‘zi kelishishiga imkon bering.',
     'Навыки дружбы растут в игре. Устраивайте короткие встречи с другими детьми, заранее потренируйтесь здороваться и предлагать игрушку. Если случилась ссора, не спешите её решать: сначала дайте детям договориться самим.',
     'Friendship skills grow through play. Arrange short play dates, and practise saying hello and offering a toy beforehand. If there is a quarrel, do not fix it at once: first let the children try to agree.',
     'Bugun salomlashishni qo‘g‘irchoqlar bilan mashq qiling.', 'Сегодня потренируйтесь здороваться с куклами.', 'Practise saying hello with toys today.'),
    (9, '5a2e0000-0000-4000-8000-000000000009', 'Emotions', 'Emotions', 2, 6, 4,
     'Jahl chiqqanda nima qilish kerak', 'Что делать, когда ребёнок злится', 'What to do when your child is angry',
     'Jahl — oddiy tuyg‘u. Avval o‘zingiz xotirjam bo‘ling, so‘ng bolaning yoniga cho‘kkalab, tuyg‘usini nomlang. Birga chuqur nafas oling: «gulni hidlaymiz, shamni puflaymiz». Tinchlangandan keyin nima bo‘lganini gaplashing.',
     'Злость — обычное чувство. Сначала успокойтесь сами, затем присядьте рядом с ребёнком и назовите его чувство. Подышите вместе: «нюхаем цветок, задуваем свечу». Когда он успокоится, поговорите о том, что случилось.',
     'Anger is a normal feeling. Calm yourself first, then crouch next to your child and name the feeling. Breathe together: "smell the flower, blow out the candle." Once calm, talk about what happened.',
     'Bugun «gul va sham» nafasini birga mashq qiling.', 'Сегодня потренируйте вместе дыхание «цветок и свеча».', 'Practise the flower and candle breath together today.'),
    (10, '5a2e0000-0000-4000-8000-000000000010', 'Emotions', 'Sleep', 2, 5, 3,
     'Uyqu va kayfiyat', 'Сон и настроение', 'Sleep and mood',
     'Yaxshi uxlamagan bola tez yig‘laydi va jahli chiqadi. Ikki-besh yoshli bolaga sutkasiga 10–13 soat uyqu kerak, kunduzgi uyqu bilan birga. Har kuni bir vaqtda yotqizish uyquni mustahkamlaydi.',
     'Невыспавшийся ребёнок чаще плачет и злится. Ребёнку от двух до пяти лет нужно 10–13 часов сна в сутки вместе с дневным сном. Укладывание в одно и то же время делает сон крепче.',
     'A tired child cries and gets angry more easily. Children aged two to five need 10 to 13 hours of sleep a day, naps included. Going to bed at the same time every day makes sleep steadier.',
     'Bugun yotish vaqtini belgilab qo‘ying.', 'Сегодня определите постоянное время отхода ко сну.', 'Pick a fixed bedtime today.')
) AS v (n, id, goal, topic, min_age, max_age, minutes, title_uz, title_ru, title_en, body_uz, body_ru, body_en,
    tip_uz, tip_ru, tip_en)
WHERE (SELECT id FROM goals WHERE deleted_at IS NULL ORDER BY created_at, id LIMIT 1) IS NOT NULL
ON CONFLICT (id) DO NOTHING;

INSERT INTO posts (id, title_uz, title_ru, title_en, video_id, goal_id, topic_id, min_age, max_age, duration,
    suggestion_uz, suggestion_ru, suggestion_en, questions_uz, questions_ru, questions_en, status, created_at, updated_at)
SELECT v.id::uuid, v.title_uz, v.title_ru, v.title_en, (SELECT id FROM media WHERE content_type LIKE 'video/%' ORDER BY created_at, id LIMIT 1),
    COALESCE((SELECT id FROM goals WHERE deleted_at IS NULL AND LOWER(name_en) = LOWER(v.goal) ORDER BY created_at, id LIMIT 1), (SELECT id FROM goals WHERE deleted_at IS NULL ORDER BY created_at, id LIMIT 1)), (SELECT id FROM topics WHERE deleted_at IS NULL AND LOWER(name_en) = LOWER(v.topic) ORDER BY created_at, id LIMIT 1),
    v.min_age, v.max_age, v.minutes, v.sug_uz, v.sug_ru, v.sug_en, v.q_uz, v.q_ru, v.q_en, 'published',
    NOW() + v.n * INTERVAL '1 millisecond', NOW()
FROM (VALUES
    (1, '5a3e0000-0000-4000-8000-000000000001', 'Language', 'Speech', 2, 4, 3.5,
     'Qo‘shiq bilan so‘z o‘rganamiz', 'Учим слова с песней', 'Learning words with a song',
     'Qo‘shiqni bola bilan birga kuylang.', 'Пойте песню вместе с ребёнком.', 'Sing the song together with your child.',
     'Qo‘shiqda qaysi hayvonlar bor edi?', 'Какие животные были в песне?', 'Which animals were in the song?'),
    (2, '5a3e0000-0000-4000-8000-000000000002', 'Language', NULL, 3, 6, 4,
     'Ertak aytib berish', 'Рассказываем сказку', 'Telling a story',
     'Videodan keyin ertakni bola o‘zi aytib bersin.', 'После видео пусть ребёнок перескажет сказку.', 'After the video, let your child retell the story.',
     'Ertak qanday tugadi?', 'Чем закончилась сказка?', 'How did the story end?'),
    (3, '5a3e0000-0000-4000-8000-000000000003', 'Motor skills', 'Play', 2, 4, 3,
     'Barmoq o‘yinlari', 'Пальчиковые игры', 'Finger games',
     'Harakatlarni bola bilan takrorlang.', 'Повторяйте движения вместе с ребёнком.', 'Repeat the moves with your child.',
     'Qaysi barmoq o‘yini yoqdi?', 'Какая пальчиковая игра понравилась?', 'Which finger game did you like?'),
    (4, '5a3e0000-0000-4000-8000-000000000004', 'Motor skills', NULL, 3, 6, 5,
     'Uyda mashqlar', 'Зарядка дома', 'Morning exercises at home',
     'Har kuni ertalab 5 daqiqa birga mashq qiling.', 'Делайте зарядку вместе по 5 минут каждое утро.', 'Exercise together for five minutes every morning.',
     'Qaysi mashq eng qiyin bo‘ldi?', 'Какое упражнение было самым трудным?', 'Which exercise was the hardest?'),
    (5, '5a3e0000-0000-4000-8000-000000000005', 'Thinking', 'Play', 2, 5, 3,
     'Ranglarni ajratamiz', 'Различаем цвета', 'Sorting colours',
     'Uydan shu rangdagi narsalarni toping.', 'Найдите дома вещи такого же цвета.', 'Find things of the same colour at home.',
     'Qizil rangli nimalar bor?', 'Что бывает красного цвета?', 'What things are red?'),
    (6, '5a3e0000-0000-4000-8000-000000000006', 'Thinking', NULL, 4, 6, 4,
     'Sanashni o‘rganamiz', 'Учимся считать', 'Learning to count',
     'Zinapoyalarni yoki olmalarni birga sanang.', 'Считайте вместе ступеньки или яблоки.', 'Count stairs or apples together.',
     'Videoda nechta qush bor edi?', 'Сколько птиц было в видео?', 'How many birds were in the video?'),
    (7, '5a3e0000-0000-4000-8000-000000000007', 'Social skills', 'Behaviour', 2, 4, 3,
     'Bo‘lishishni o‘rganamiz', 'Учимся делиться', 'Learning to share',
     'Bugun bitta o‘yinchoqni navbat bilan o‘ynang.', 'Сегодня поиграйте одной игрушкой по очереди.', 'Take turns with one toy today.',
     'Qahramon nima uchun xursand bo‘ldi?', 'Почему герой обрадовался?', 'Why was the hero happy?'),
    (8, '5a3e0000-0000-4000-8000-000000000008', 'Social skills', NULL, 4, 6, 4,
     'Sehrli so‘zlar', 'Волшебные слова', 'Magic words',
     '«Rahmat» va «iltimos» so‘zlarini kun davomida ishlating.', 'Используйте «спасибо» и «пожалуйста» весь день.', 'Use "thank you" and "please" all day.',
     'Qanday sehrli so‘zlarni bilasan?', 'Какие волшебные слова ты знаешь?', 'Which magic words do you know?'),
    (9, '5a3e0000-0000-4000-8000-000000000009', 'Emotions', 'Emotions', 2, 6, 3.5,
     'Tuyg‘ular yuzi', 'Лица эмоций', 'Faces of feelings',
     'Ko‘zgu oldida turli tuyg‘ularni ko‘rsating.', 'Покажите разные эмоции перед зеркалом.', 'Show different feelings in front of a mirror.',
     'Qahramon qachon xafa bo‘ldi?', 'Когда герой расстроился?', 'When was the hero sad?'),
    (10, '5a3e0000-0000-4000-8000-000000000010', 'Emotions', 'Sleep', 2, 5, 4,
     'Uyqu oldidan tinchlanish', 'Успокаиваемся перед сном', 'Calming down before sleep',
     'Videodan keyin chiroqni pasaytirib, sekin gaplashing.', 'После видео приглушите свет и говорите тихо.', 'After the video, dim the lights and talk softly.',
     'Bugun nima seni xursand qildi?', 'Что тебя сегодня порадовало?', 'What made you happy today?')
) AS v (n, id, goal, topic, min_age, max_age, minutes, title_uz, title_ru, title_en, sug_uz, sug_ru, sug_en,
    q_uz, q_ru, q_en)
WHERE (SELECT id FROM goals WHERE deleted_at IS NULL ORDER BY created_at, id LIMIT 1) IS NOT NULL AND (SELECT id FROM media WHERE content_type LIKE 'video/%' ORDER BY created_at, id LIMIT 1) IS NOT NULL
ON CONFLICT (id) DO NOTHING;
